CREATE TABLE `outbox_events` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `event_type` enum('order_created','order_assigned','order_supplier_preparing','order_supplier_delivering','order_market_inspecting','order_market_accepted','order_market_delivering','order_customer_inspecting','order_completed','order_return_requested','order_exchange_requested','order_exchange_in_progress','order_exchange_delivering','order_exchange_inspecting','order_exchange_new_delivering','order_exchange_completed','order_cancelled','order_returned') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '订单事件类型',
  `payload` json NOT NULL COMMENT '事件数据',
  `processed` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否已处理',
  `retry_count` int unsigned NOT NULL DEFAULT '0' COMMENT '重试次数',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `processed_at` timestamp NULL DEFAULT NULL,
  `exclude_tenant_type` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
