ist','获取产品价格列表','审核员，询价员根据当日产品价格状态查询','GET','/api/v1/product_prices/status',NULL),(55,'product:list','获取产品列表','获取指定市场产品列表','GET','/api/v1/tenants/{hashed_name}/products',0),(56,'product:update','编辑产品信息','编辑产品信息，只有产品所有者才有权限','PUT','/api/v1/tenants/{hashed_name}/products/{id}',0),(57,'product:read','查看产品详情','查看产品详情','GET','/api/v1/products/{id}',0),(58,'processing:read','查看产品详情','查看产品详情','GET','/api/v1/processing-fees',0),(59,'product:disable','下架产品','下架或禁用产品','DELETE','/api/v1/tenants/{hashed_name}/products/{id}/archive',0),(60,'product:enable','上架产品','上架产品','PATCH','/api/v1/tenants/{hashed_name}/products/{id}/enable',0),(61,'product:list','获取产品列表','客户获取产品列表','GET','/api/v1/customers/{tenant_hash}/products',0),(62,'tenant:list','获取租户列表','获取租户列表','GET','/api/v1/tenants',0),(63,'tenant:read','获取租户信息','市场管理员获取租户信息','GET','/api/v1/tenants/{hashed_name}',0),(64,'user:enable','启用用户','管理员启用用户','PATCH','/api/v1/tenants/{hashed_name}/users/{username}/enable',0),(65,'discount:list','获取折扣列表','市场管理员获取客户折扣','GET','/api/v1/tenants/{hashed_name}/discounts',0),(66,'discount:create','添加折扣','市场管理员设置客户折扣','POST','/api/v1/tenants/{hashed_name}/discounts',0),(67,'discount:update','修改折扣','市场管理员修改客户折扣','PATCH','/api/v1/tenants/{hashed_name}/discounts/{id}',0),(68,'order:complete','验收通过','市场/客户验收订单通过-主订单','PATCH','/api/v1/orders/{order_code}/complete-inspection',0),(69,'order:exchange','市场/客户换货','市场/客户发起换货请求','POST','/api/v1/orders/{order_code}/after-sales',0),(70,'order:inspect','验收子订单','换货验收子订单','PATCH','/api/v1/orders/{order_code}/begin-exchange-inspect-order',0),(71,'order:exchange','处理换货','订单换货流程','PATCH','/api/v1/orders/{order_code}/deliver-exchange-to-market',0),(72,'order:exchange','开始换货','确认要执行换货流程','POST','/api/v1/orders/{order_code}/accept-after-sales',0),(73,'order:list','退换货商品列表','获取退换货商品列表','GET','/api/v1/orders/{order_code}/exchange-and-return-order-details',0),(74,'order:prepare','处理换货','供应商处理换货','PATCH','/api/v1/orders/{order_code}/exchange-items/{order_detail_id}',0),(75,'